// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadGreatVibes = makeLoadFont('GreatVibes');
const loadInter = makeLoadFont('Inter');

// Module-level font loading for reliable Lambda renders
const { fontFamily: cursiveFamily } = loadGreatVibes();
const { fontFamily: sansFamily } = loadInter();



export type ComponentNameProps = Record<string, any>;

const TextHookAnimation: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = true,
  durationInSeconds = 5,
  supportingText = "MALLOY STUDIO",
  mainText = "Malloy Studio",
  bottomText = "ESTABLISHED IN 2025",
  textColor = "#fff4e0",
  glowColor = "#ff9f43",
  supportingFontSize = 32,
  mainFontSize = 160,
  bottomFontSize = 18,
  flickerIntensity = 0.85,
  enableFlares = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Supporting Text (Top) Slide Up Animation
  const supportingSpring = spring({
    frame: frame - 4,
    fps,
    config: {
      damping: 14,
      stiffness: 90,
      mass: 0.8,
    },
  });

  const supportingY = interpolate(supportingSpring, [0, 1], [40, 0]);
  const supportingOpacity = interpolate(supportingSpring, [0, 1], [0, 1]);
  const supportingLetterSpacing = interpolate(supportingSpring, [0, 1], [4, 16]);

  // 2. Main Cursive Text Slide Up Animation
  const mainSpring = spring({
    frame: frame - 16,
    fps,
    config: {
      damping: 14,
      stiffness: 70,
      mass: 1.1,
    },
  });

  const mainY = interpolate(mainSpring, [0, 1], [110, 0]);
  const mainScale = interpolate(mainSpring, [0, 1], [0.8, 1]);
  const mainRotate = interpolate(mainSpring, [0, 1], [-4, 0]);

  // 3. Bottom Text Slide Up Animation
  const bottomSpring = spring({
    frame: frame - 28,
    fps,
    config: {
      damping: 16,
      stiffness: 80,
      mass: 0.9,
    },
  });

  const bottomY = interpolate(bottomSpring, [0, 1], [40, 0]);
  const bottomOpacity = interpolate(bottomSpring, [0, 1], [0, 1]);
  const bottomLetterSpacing = interpolate(bottomSpring, [0, 1], [2, 8]);

  // 4. Flicker and Ignition Sequence
  const ignitionStart = 15;
  const ignitionEnd = 40;
  
  const rawNoise = random(`flicker-frame-${frame}`);
  
  let flickerFactor = 1.0;
  if (frame >= ignitionStart && frame < ignitionEnd) {
    if (rawNoise < 0.2) {
      flickerFactor = 0.1;
    } else if (rawNoise < 0.45) {
      flickerFactor = 0.4;
    } else if (rawNoise < 0.7) {
      flickerFactor = 0.85;
    } else {
      flickerFactor = 0.05;
    }
  } else if (frame < ignitionStart) {
    flickerFactor = 0;
  } else {
    flickerFactor = 0.96 + 0.04 * Math.sin(frame * 0.4);
  }

  const baseFadeIn = interpolate(frame, [15, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const targetOpacity = baseFadeIn * (1 - flickerIntensity + flickerFactor * flickerIntensity);

  const glowPulse = interpolate(
    Math.sin(frame * 0.25),
    [-1, 1],
    [0.9, 1.1]
  );

  const textShadowStyle = `
    0 0 ${12 * glowPulse}px ${glowColor}66,
    0 0 ${25 * glowPulse}px ${glowColor}44,
    0 0 ${50 * glowPulse}px ${glowColor}22
  `;

  // Horizontal Flares Animation (Warm Gold Streaks)
  const flareSpring = spring({
    frame: frame - 22,
    fps,
    config: {
      damping: 18,
      stiffness: 60,
    },
  });

  const flareScaleX = interpolate(flareSpring, [0, 1], [0, 1]);
  const flareOpacity = interpolate(flareSpring, [0, 1], [0, 0.75]) * flickerFactor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
          width: "100%",
          padding: `0 ${width * 0.05}px`,
          boxSizing: "border-box",
        }}
      >
        {/* Supporting Text (Top) */}
        <div
          style={{
            fontFamily: sansFamily,
            fontSize: `${supportingFontSize}px`,
            fontWeight: "700",
            color: textColor,
            textTransform: "uppercase",
            letterSpacing: `${supportingLetterSpacing}px`,
            opacity: supportingOpacity * targetOpacity,
            transform: `translateY(${supportingY}px)`,
            marginBottom: "24px",
            textShadow: `0 0 10px ${glowColor}33`,
            transition: "none",
          }}
        >
          {supportingText}
        </div>

        {/* Main Cursive / Calligraphy Text Container */}
        <div
          style={{
            position: "relative",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `translateY(${mainY}px) scale(${mainScale}) rotate(${mainRotate}deg)`,
            opacity: targetOpacity,
            transition: "none",
          }}
        >
          {/* Main Glowing Cursive Text */}
          <span
            style={{
              fontFamily: cursiveFamily,
              fontSize: `${mainFontSize}px`,
              color: textColor,
              textShadow: textShadowStyle,
              lineHeight: 1.1,
              whiteSpace: "nowrap",
              padding: "0 40px",
              zIndex: 2,
            }}
          >
            {mainText}
          </span>

          {/* Golden Horizontal Flares */}
          {enableFlares && (
            <div
              style={{
                position: "absolute",
                width: "120%",
                height: "2px",
                top: "55%",
                left: "-10%",
                background: `linear-gradient(90deg, transparent, ${glowColor}cc 30%, #fff 50%, ${glowColor}cc 70%, transparent)`,
                transform: `scaleX(${flareScaleX})`,
                opacity: flareOpacity,
                pointerEvents: "none",
                zIndex: 1,
                boxShadow: `0 0 8px ${glowColor}`,
                transition: "none",
              }}
            />
          )}

          {/* Secondary subtle offset flare line */}
          {enableFlares && (
            <div
              style={{
                position: "absolute",
                width: "90%",
                height: "1px",
                top: "45%",
                left: "5%",
                background: `linear-gradient(90deg, transparent, ${glowColor}88 20%, #fff 50%, ${glowColor}88 80%, transparent)`,
                transform: `scaleX(${flareScaleX * 0.85})`,
                opacity: flareOpacity * 0.7,
                pointerEvents: "none",
                zIndex: 1,
                boxShadow: `0 0 6px ${glowColor}88`,
                transition: "none",
              }}
            />
          )}
        </div>

        {/* Bottom Supporting Text */}
        <div
          style={{
            fontFamily: sansFamily,
            fontSize: `${bottomFontSize}px`,
            fontWeight: "600",
            color: textColor,
            textTransform: "uppercase",
            letterSpacing: `${bottomLetterSpacing}px`,
            opacity: bottomOpacity * targetOpacity,
            transform: `translateY(${bottomY}px)`,
            marginTop: "32px",
            textShadow: `0 0 8px ${glowColor}22`,
            transition: "none",
          }}
        >
          {bottomText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TextHookAnimation;